import{z as i,x as s,o as r,c as l,q as t,j as B,D as a,d as e,s as A,S as m,b as o}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"公地悲剧","description":"","frontmatter":{"title":"公地悲剧","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/common-pool.md","filePath":"econ/common-pool.md","lastUpdated":1791413859000}'),d={name:"econ/common-pool.md"};function p(h,E,P,c,D,f){const n=s("Mermaid");return r(),l("div",null,[E[2]||(E[2]=t('<h1 id="公地悲剧" tabindex="-1">公地悲剧 <a class="header-anchor" href="#公地悲剧" aria-label="Permalink to &quot;公地悲剧&quot;">​</a></h1><div class="epigraph"><p>资源可分、却很难把使用者关在门外时，每人按平均收益进入，直到租金耗尽；这是捕获，不是俱乐部会费。</p><footer>—— 据 Gordon, The Economic Theory of a Common-Property Resource: The Fishery, Journal of Political Economy, 1954；Hardin, The Tragedy of the Commons, Science, 1968 整理</footer></div><p><a href="/econ/club-goods">上一课</a>（俱乐部物品）。排他立住时，拥挤由会费与最优 \\(n\\) 内部化。本课不重写摊薄对拥挤的切。缺口是排他失败、但消费是竞争的：多捕一吨鱼，别人少捕一吨。Gordon 的渔场把进入钉在平均产品等于机会工资；Hardin 把它写成「公地悲剧」。Ostrom 对照一句：社区可以自定规则，不必只在国有化与私有化之间选。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>公共池塘：消费可分（rival），排除成本高。进入自由时，每人看到的是平均产品 \\(\\mathrm{AP}\\)，不是边际产品 \\(\\mathrm{MP}\\)。均衡：\\(\\mathrm{AP}(E)=w\\)，努力 \\(E\\) 超过社会最优 \\(\\mathrm{MP}(E)=w\\)，租金 \\(\\int(\\mathrm{MP}-w)\\) 被耗尽。缺口不是再写俱乐部的 \\(u(X,n)\\)，而是：<strong>平均对边际的缺口怎样把租吃光，以及这与纯公共品免费搭车不是同一博弈。</strong></p><p><span class="marginnote">术语翻译：平均产品 \\(\\mathrm{AP}=f(E)/E\\) 是「平摊到每份努力上的收成」，边际产品 \\(\\mathrm{MP}=f&#39;(E)\\) 是「多下一网给<strong>全湖</strong>加的产量」。开放进入下，新来的渔民只数自己网里的鱼（看 AP），不数他被拥挤挤掉的别人那份（MP 比 AP 低的那段），于是船越进越多，直到平均收成只够工资。</span></p><p>纯公共品：多用一人不减别人的 \\(G\\)，问题是供给不足。公地：取用过多，存量或租金过少。俱乐部：能收费，故能停在 \\(n^*\\)。公地收不上会费，进入直到租为零——像<a href="/econ/long-run-entry">长期进入</a>的零利润，但「利润」来自稀缺自然资源，耗尽是浪费不是正常回报。</p><h3 id="hardin-不是唯一制度处方" tabindex="-1">Hardin 不是唯一制度处方 <a class="header-anchor" href="#hardin-不是唯一制度处方" aria-label="Permalink to &quot;Hardin 不是唯一制度处方&quot;">​</a></h3><p>Hardin 的叙事推向圈地或利维坦。Gordon 的渔场已经是价格接受下的开放进入模型，处方是进入限制或税费把 \\(E\\) 拉回 \\(\\mathrm{MP}=w\\)。Ostrom：占用者重复互动、监测、分级制裁，可以把规则变成事实上的排他——接近俱乐部，但产权不一定是私人土地证。本课对照一句即收，不把治理案例写成教材。</p><p><span class="marginnote">Gordon 1954：开放渔场的租耗尽。Hardin 1968 是随笔式推广。引用时分开：一个是平均产品均衡，一个是道德叙事。Ostrom, <em>Governing the Commons</em>, 1990 是制度对照，不是否定 Gordon 的开放进入算术。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>静态渔场：\\(q=f(E)\\) 凹，\\(f(0)=0\\)。社会最优 \\(\\max f(E)-wE\\)。开放进入：若渔人很多、鱼价标准化为 1，每人进入直到 \\(f(E)/E=w\\)。两条曲线的水平距离就是过度进入。动态存量、生物增长，把 \\(f\\) 换成可持续产量，逻辑不变：开放进入吃掉资源租。</p><p>税费 \\(t\\) 使 \\((1-t)\\mathrm{AP}=w\\) 或按捕捞征相当于 \\(t\\) 的许可，可以把 \\(E\\) 拉回最优——与<a href="/econ/cap-and-trade">总量管制</a>同一类工具：渔获配额可交易，则回到许可市场。排他一旦便宜，问题退回俱乐部。开放进入的零租不是「正常回报」，而是稀缺资源的浪费。</p>',13)),(r(),B(m,null,{default:a(()=>[A(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20CLUB%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%EF%BC%9A%E8%83%BD%E6%8E%92%EF%BC%8C%E4%BC%9A%E8%B4%B9%E9%92%89%20n*%22%5D%20--%3E%20CP%5B%22%E4%B8%8D%E8%83%BD%E6%8E%92%EF%BC%8C%E5%8F%96%E7%94%A8%E5%8F%AF%E5%88%86%22%5D%0A%20%20CP%20--%3E%20AP%5B%22%E8%BF%9B%E5%85%A5%E7%9B%B4%E5%88%B0%20AP%20%3D%20w%22%5D%0A%20%20AP%20--%3E%20RENT%5B%22%E8%B5%84%E6%BA%90%E7%A7%9F%E8%80%97%E5%B0%BD%22%5D%0A%20%20CP%20--%3E%20OST%5B%22Ostrom%EF%BC%9A%E7%A4%BE%E5%8C%BA%E8%A7%84%E5%88%99%E5%8F%AF%E8%BF%91%E4%BC%BC%E6%8E%92%E4%BB%96%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=o("p",null,"不要把公地写成纯公共品供给不足。一个是取太多，一个是建太少。",-1)),E[4]||(E[4]=o("h2",{id:"机制",tabindex:"-1"},[e("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=o("p",null,"AP 对 MP 的机制是未定价的拥挤：我多下一网，全体平均下降，我只感到自己的平均，不付别人的边际损失。这是负外部性，庇古税或配额对准的就是 \\(\\mathrm{AP}-\\mathrm{MP}\\) 那一段。零租的机制是自由进入：正租吸引下一艘船，直到平均只够工资。",-1)),(r(),B(m,null,{default:a(()=>[A(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20ME%5B%22%E6%88%91%E5%A4%9A%E4%B8%8B%E4%B8%80%E7%BD%91%EF%BC%9A%E8%87%AA%E5%B7%B1%E7%BD%91%E9%87%8C%E5%A4%9A%E5%87%A0%E6%9D%A1%E9%B1%BC%22%5D%20--%3E%20IGNORE%5B%22%E7%9C%8B%E4%B8%8D%E8%A7%81%EF%BC%9A%E5%85%A8%E6%B9%96%E6%AF%8F%E6%9D%A1%E8%88%B9%E7%9A%84%E6%94%B6%E6%88%90%E8%A2%AB%E6%8B%89%E4%BD%8E%E4%B8%80%E7%82%B9%22%5D%0A%20%20IGNORE%20--%3E%20ALL%5B%22%E6%AF%8F%E5%AE%B6%E9%83%BD%E8%BF%99%E4%B9%88%E7%AE%97%EF%BC%9A%E6%80%BB%E5%8A%AA%E5%8A%9B%20E%20%E4%B8%80%E8%B7%AF%E5%8A%A0%E7%A0%81%22%5D%0A%20%20ALL%20--%3E%20AP%5B%22%E5%B9%B3%E5%9D%87%E4%BA%A7%E9%87%8F%20AP%20%E4%B8%80%E8%B7%AF%E4%B8%8B%E6%BB%91%22%5D%0A%20%20AP%20--%3E%20ZERO%5B%22AP%20%3D%20%E5%B7%A5%E8%B5%84%20w%EF%BC%9A%E5%86%8D%E5%A4%9A%E6%8D%9E%E5%8F%AA%E5%A4%9F%E7%B3%8A%E5%8F%A3%EF%BC%8C%E7%A7%9F%E5%BD%92%E9%9B%B6%22%5D%0A%20%20FIX%5B%22%E5%BA%87%E5%8F%A4%E7%A8%8E%20%2F%20%E5%8F%AF%E4%BA%A4%E6%98%93%E9%85%8D%E9%A2%9D%22%5D%20--%3E%20BILL%5B%22%E6%8A%8A%E6%88%91%E5%BC%BA%E5%8A%A0%E7%BB%99%E5%88%AB%E4%BA%BA%E7%9A%84%E8%BE%B9%E9%99%85%E6%8D%9F%E5%A4%B1%E8%AE%B0%E8%BF%9B%E6%88%91%E7%9A%84%E8%B4%A6%22%5D%0A%20%20BILL%20--%3E%20OPT%5B%22%E5%9B%9E%E5%88%B0%20MP%20%3D%20w%20%E7%9A%84%E7%A4%BE%E4%BC%9A%E6%9C%80%E4%BC%98%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<p><span class="marginnote">数字实例：湖上 10 条船日均各捕 100 公斤，第 11 条船进来后每条降到 95 公斤。新船自己看到的是 95 公斤的进账；全湖总产量只从 1000 涨到 1045——它的真实边际贡献只有 45 公斤。只要 95 高于出海成本，船还会继续进，哪怕多一条船全社会几乎没多一条鱼。</span></p><p>与俱乐部对照：会费是排他价格，把 \\(n\\) 停在人均净收益最大；公地没有这道门，进入者只比工资。与科斯对照：渔民很多，双边谈判组不起来，标准化配额比一对一谈判更像许可课。</p><p>动态存量：开放进入不仅吃当期租，还把繁殖基数打薄，下期 \\(f\\) 内移。静态 \\(\\mathrm{AP}=w\\) 已经浪费；加上生物增长，可能停在更低的稳态甚至崩溃。配额若可交易，把动态帽交给许可市场，逻辑与排放课相同，只是再生约束替换 \\(\\mathrm{MD}\\)。</p><p><span class="marginnote">「公地」在法律上常指共同产权，不一定是开放进入。Gordon–Hardin 的算术针对开放进入。共同产权加规则，可以不是悲剧——这正是 Ostrom 与 Hardin 差的那一句。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>国际公海比封闭渔场更接近 Hardin：排他成本高、占用者跨主权。</p><p><span class="marginnote">常见误区：把公地悲剧读成「人性自私，注定无解」。Ostrom 的田野记录恰相反：无数渔场、牧场、灌溉系统靠社区自定配额、轮值、分级罚款维持了几百年，既没私有化也没等政府接管。悲剧的前提是「没人能立规矩」，而不是「人皆自私」——一旦规则被承认并执行，算术就会被改写。</span></p><p>动态崩溃（存量掉到再生产以下）比静态租耗尽更狠，本课静态已够机制。全球大气更接近公共品加公地的混合。下一课<a href="/econ/lindahl-samuelson">林达尔</a>回到纯公共品的分权价格，不问渔场。</p><p>后课默认：开放进入的可分资源停在 \\(\\mathrm{AP}=w\\)，资源租耗尽；能排他则回到俱乐部；Ostrom 说规则可以制造排他，不是否定算术。</p><p>本课不把开放进入的零租写成正常回报。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可分且难排他：进入看平均产品，租被吃光。</li><li>这是过度取用，不是纯公共品的供给不足。</li><li>Hardin 推向圈地或国家；Gordon 给出渔场均衡；Ostrom 加一句社区规则。</li><li>配额与税对准的是 \\(\\mathrm{AP}-\\mathrm{MP}\\)。</li><li>出处：Gordon, <em>JPE</em>, 1954；Hardin, <em>Science</em>, 1968；Ostrom, 1990。</li></ul>',12))])}const u=i(d,[["render",p]]);export{C as __pageData,u as default};
